export function productionCatalogue(g:Game,team=0){
 const t=g.tribe(team);
 const buildings=BUILD_ORDER.map(id=>{const def=BUILDINGS[id],cost=buildingCost(id,g,team),sites=g.state.buildings.filter(b=>b.team===team&&b.type===id&&b.hp>0),complete=sites.filter(b=>g.finished(b)),missing=Object.entries(cost).filter(([key,n])=>Number(n)>Number(t[key as keyof typeof t]||0)).map(([key,n])=>`${Math.ceil(Number(n)-Number(t[key as keyof typeof t]||0))} ${key==='wood'?'logs':key}`),ageIssue=t.age<def.age?`Requires ${AGES[def.age]} stage`:null,practiceIssue=id==='farm'?cultivationIssue(g):null;
 return{id,name:def.name,hint:def.hint,cost,complete:complete.length,unfinished:sites.length-complete.length,siteStates:sites.filter(b=>!g.finished(b)).map(b=>planStatus(g,b)),blockers:[...(ageIssue?[ageIssue]:[]),...(practiceIssue?[practiceIssue]:[]),...(missing.length?[`Need ${missing.join(', ')}`]:[])],canChooseSite:!ageIssue&&!practiceIssue,age:AGES[def.age]};});
 const recipes=(Object.entries(PRODUCTION_RECIPES) as [ProductionRecipe,(typeof PRODUCTION_RECIPES)[ProductionRecipe]][]).map(([id,r])=>{const sites=g.state.buildings.filter(b=>b.team===team&&b.type===r.workplace&&g.finished(b));return{...r,id,workSeconds:productionWorkSeconds(id),workplaceName:BUILDINGS[r.workplace].name,slots:productionSlots({type:r.workplace}),sites:sites.map(b=>({id:b.id,slots:productionSlots(b),issue:productionIssue(g,id,b.id)})),inputsText:[...(r.grain?[`${r.grain} grain`]:[]),...Object.entries(r.foodInputs).map(([k,n])=>`${n} ${FOOD_NAMES[k as FoodKind]}`),...Object.entries(r.inputs).map(([k,n])=>`${n} ${ITEM_NAMES[k as ItemKind]}`),...(r.wood?[`${r.wood} logs`]:[]),...(r.water?[`${r.water} litres water`]:[])].join(' · '),outputsText:[...Object.entries(r.outputs).map(([k,n])=>`${k==='pottery'?'up to ':''}${n} ${ITEM_NAMES[k as ItemKind]}${k==='pottery'?' (failed units become potsherds)':''}`),...(r.food?[`${r.food} ${FOOD_NAMES[r.foodKind]}`]:[])].join(' · ')};});
 return{buildings,recipes,production:team===0?productionStatus(g):null,roles:PRODUCTION_ROLES.map(r=>({...r,activeRecipes:recipes.filter(x=>r.buildingIds.includes(x.workplace)&&(r.id!=='pottery'||['formClayHand','formClay','dryClay','dryClayCovered','fireClayHand','fireClay'].includes(x.id))&&(r.id!=='foodDryer'||x.preservation==='air')&&(r.id!=='skinDryer'||x.id==='drySkin')&&(r.id!=='smokehouse'||x.preservation==='smoke')&&(r.id!=='mortar'||x.id.startsWith('grindGrain'))&&(r.id!=='oven'||x.id.startsWith('bakeBread'))),sites:buildings.filter(b=>r.buildingIds.includes(b.id)),registered:r.buildingIds.some(id=>id in BUILDINGS)}))};
}
export function catalogueBuildingId(value:string):BldType|null{return Object.hasOwn(BUILDINGS,value)?value as BldType:null;}

