export function filterProductionStations(query="",stage:ProductionStage|"all"="all",status:"all"|"available"|"planned"="all"){const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return PRODUCTION_STATIONS.filter(s=>(stage==="all"||s.stage===stage)&&(status==="all"||(status==="planned"?s.status==="planned":s.status!=="planned"))&&terms.every(term=>[s.name,s.function,s.dependencies,s.manualPredecessor,s.measure,s.roleId].join(" ").toLowerCase().includes(term)));}
